void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = (fragCoord.xy - 0.5 * u_resolution.xy) / u_resolution.y;
  float t = u_time * 0.4 * u_speed;
  vec3 col = vec3(0.01, 0.02, 0.05);
  float wave1 = sin(uv.x * 3.0 + t) * 0.2;
  float wave2 = cos(uv.x * 5.0 - t * 0.7) * 0.15;
  float dist = abs(uv.y - wave1 - wave2);
  float aurora = 0.04 / (dist + 0.02);
  col += u_color2 * aurora * (0.8 + u_audio_bass * 0.4);
  col += u_accent * (aurora * 0.5) * smoothstep(-0.2, 0.4, uv.y);
  fragColor = vec4(col * u_intensity, 1.0);
}
